import { Order, OrderState, canTransitionTo } from '../domain/Order';
import { OrderRepository } from '../domain/OrderRepository';

export interface UpdateOrderStateRequest {
  orderId: string;
  newState: OrderState;
}

export class UpdateOrderStateUseCase {
  constructor(private orderRepository: OrderRepository) {}

  execute(request: UpdateOrderStateRequest): Order {
    const order = this.orderRepository.getById(request.orderId);
    if (!order) {
      throw new Error(`Order ${request.orderId} not found`);
    }

    if (!canTransitionTo(order.state, request.newState)) {
      throw new Error(
        `Cannot transition from ${order.state} to ${request.newState}`,
      );
    }

    order.state = request.newState;
    this.orderRepository.save(order);
    return order;
  }
}

